// -----------------------------------------------------------------------------
// Journey Booking — Confirm Request DTO
// -----------------------------------------------------------------------------

import { ApiPropertyOptional } from '@nestjs/swagger';
import { IsDateString, IsOptional } from 'class-validator';

/**
 * Optional request payload for confirming a Journey Booking.
 *
 * The booking public ID is supplied through the route parameter.
 * The correlation ID is generated by the controller.
 *
 * Payment confirmation details, such as transactionPublicId, belong to
 * AuthorizeJourneyBookingPaymentDto when required by the endpoint.
 */
export class ConfirmJourneyBookingDto {
  @ApiPropertyOptional({
    description:
      'Explicit confirmation timestamp. When omitted, the application uses the current time.',
    example: '2026-08-18T13:45:00.000Z',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  confirmedAt?: string;
}

export default ConfirmJourneyBookingDto;
